#!/usr/bin/env bash
# Workstation, tools, cluster, Ingress and access of this installation, for support. Read-only: it
# changes nothing (the access check uses kubectl port-forward in the background). Generated by the
# DX Installer Wizard v2.7.0-dev; ./install.sh --collect includes its output.
#   support/environment-info.sh                         print the report
#   support/environment-info.sh > environment-info.txt  to send it
set -uo pipefail
cd "$(dirname "$0")/.."
sec() { printf '\n===== %s =====\n' "$*"; }
run() { printf '$ %s\n' "$1"; bash -c "$1" 2>&1 | head -n "${2:-200}"; }

sec "Installation (BUILD-INFO.txt)"
cat BUILD-INFO.txt 2>/dev/null || echo "BUILD-INFO.txt not found (folder generated before installer 2.6)"

sec "Workstation"
run "date -u"
run "uname -a"
run "grep -E '^(PRETTY_NAME|VERSION_ID)=' /etc/os-release"
if grep -qi microsoft /proc/version 2>/dev/null; then
  echo "WSL: yes"
  run "cat /etc/wsl.conf"
  run "ls /mnt/c/Users/*/.wslconfig 2>/dev/null | head -3 | xargs -r cat"     # networkingMode (NAT / mirrored)
  run "grep -i 'dx-demo.apps.promox.europesip-lab.com' /mnt/c/Windows/System32/drivers/etc/hosts"
else echo "WSL: no"; fi
run "ps -p 1 -o comm="                                                    # systemd or not
run "nproc; free -h; df -h ."

sec "Tools"
run "kubectl version --client"
run "helm version"
run "openssl version; curl --version | head -1; python3 --version"
run "command -v k3s >/dev/null && k3s --version"

sec "Cluster"
run "kubectl config current-context"
run "kubectl version"
run "kubectl get nodes -o wide"
run "kubectl get storageclass"
run "kubectl get ingressclass"

sec "Ingress controller"
run "kubectl get pods,svc -A -o wide -l 'app.kubernetes.io/name in (traefik,ingress-nginx,rke2-ingress-nginx)'"
run "kubectl get svc -A --field-selector spec.type=LoadBalancer -o wide"
run "kubectl -n kube-system get helmchartconfig,helmchart 2>/dev/null"      # k3s: the configuration of its Traefik

sec "How DX is exposed (dx-demo)"
run "kubectl -n dx-demo get ingress,ingressroute.traefik.io,serverstransport.traefik.io,middleware.traefik.io -o wide"
run "kubectl -n dx-demo get svc dx-deployment-haproxy -o wide; kubectl -n dx-demo get endpointslices -l kubernetes.io/service-name=dx-deployment-haproxy"
run "kubectl -n dx-demo describe ingress 2>/dev/null" 80

sec "Pods and Helm releases"
run "kubectl -n dx-demo get pods -o wide"
run "kubectl -n dx-shared get pods -o wide"
run "helm list -A"

sec "Name resolution and ports of this machine"
run "getent hosts dx-demo.apps.promox.europesip-lab.com"
run "grep -i 'dx-demo.apps.promox.europesip-lab.com' /etc/hosts"
run "ss -ltn '( sport = :80 or sport = :443 )'"

sec "Access to DX, layer by layer"
H=dx-demo.apps.promox.europesip-lab.com
http_ok() { case "$1" in 2??|3??) echo "OK ($1)" ;; *) echo "FAIL (HTTP $1)" ;; esac; }
http_code() { curl -sk -o /dev/null --max-time 20 -w '%{http_code}' "$@" || true; }   # 000 = no connection
pf_start() { kubectl "$@" >/dev/null 2>&1 & PF=$!; sleep 4; }                          # port-forward in the background
pf_stop() { kill $PF 2>/dev/null; wait $PF 2>/dev/null || true; }
# 1 · DX itself (its HAProxy), without the Ingress, DNS or ports 80/443
pf_start -n dx-demo port-forward svc/dx-deployment-haproxy 18443:443
echo "1 · DX (HAProxy, port-forward)          : $(http_ok $(http_code --resolve $H:18443:127.0.0.1 https://$H:18443/wps/portal))"; pf_stop
# 2 · The Ingress controller and the route of DX, without DNS or ports 80/443
read -r INS ISVC _ < <(kubectl get svc -A -l app.kubernetes.io/name=ingress-nginx,app.kubernetes.io/component=controller --no-headers 2>/dev/null | grep -v admission | head -1) || true
if [ -n "${ISVC:-}" ]; then pf_start -n $INS port-forward svc/$ISVC 19443:443
  echo "2 · Ingress controller $ISVC (port-forward): $(http_ok $(http_code --resolve $H:19443:127.0.0.1 https://$H:19443/wps/portal))"; pf_stop
else echo "2 · Ingress controller: no Service found with -l app.kubernetes.io/name=ingress-nginx,app.kubernetes.io/component=controller"; fi
# 3 · Port 443 of the controller from this machine, without DNS
# candidates: the LoadBalancer address, the external and internal address of a node, the address the name resolves to
# (in a cloud the LoadBalancer of k3s and the node show private addresses this machine may not reach): the first that answers
CANDS="$(kubectl -n "${INS:-x}" get svc "${ISVC:-x}" -o jsonpath='{.status.loadBalancer.ingress[0].ip}' 2>/dev/null || true) $(kubectl get nodes -o jsonpath='{.items[0].status.addresses[?(@.type=="ExternalIP")].address}' 2>/dev/null || true) $(kubectl get nodes -o jsonpath='{.items[0].status.addresses[?(@.type=="InternalIP")].address}' 2>/dev/null || true) $(getent hosts $H | awk '{print $1}' | head -1 || true)"
IP=; C3=000; for c in $CANDS; do C3=$(http_code --resolve $H:443:$c https://$H/wps/portal); case $C3 in 2??|3??) IP=$c; break ;; esac; done
[ -n "$IP" ] || IP=$(echo $CANDS | awk '{print $1}')
echo "3 · Port 443 of $IP (no DNS)            : $(http_ok $C3)"
# 4 · The real URL (DNS + everything)
echo "4 · https://$H ($(getent hosts $H | awk '{print $1}' | head -1 || true))  : $(http_ok $(http_code https://$H/wps/portal))"
echo "1 fails: DX is not ready · 1 OK, 2 fails: the route (lab-base/ingress-dx.yaml) or the controller · 2 OK, 3 fails: ports 80/443 do not reach the controller (firewall, LoadBalancer, WSL) · 3 OK, 4 fails: the DNS or hosts file of $H"
echo "All OK here but the browser of Windows fails (k3s in WSL): docs/troubleshooting.md of the installer, ports 80/443"

sec "Recent warnings"
run "kubectl get events -A --field-selector type=Warning --sort-by=.lastTimestamp | tail -40"
